function manualAiFallback(requestMode,text){if(!ensureAiMode(requestMode))return;const exact=typeof text==='string'?text:'';if(exact.length>4000){toast('文字过长，请缩短后再手动记录');return;}invalidateAiMode(requestMode);clearAiRetry();clearPendingAi();aiLastRequest=null;aiLastFoodContext=null;aiInputRevision++;aiManualReference=Object.freeze({mode:requestMode,text:exact});$('ai-manual-reference-text').textContent=exact;$('ai-manual-reference-text').hidden=!exact;$('ai-manual-reference').hidden=false;aiCaptureHost(requestMode).append($('ai-manual-reference'));$('ai-task-status').hidden=true;openManualReference();}
$('ai-manual-open').addEventListener('click',openManualReference);$('ai-manual-dismiss').addEventListener('click',clearManualReference);
