function showAiStatus(requestMode,phase,message){const panel=$('ai-task-status'),dialog=$(requestMode==='food'?'food-dialog':'review-dialog'),host=dialog.open?(requestMode==='food'?$('food-form'):dialog):aiCaptureHost(requestMode);if(panel.parentElement!==host){if(dialog.open)host.insertBefore(panel,host.children[1]||null);else host.append(panel);}panel.hidden=false;panel.dataset.phase=phase;panel.dataset.mode=requestMode;const busy=['preparing','consent','sending'].includes(phase),messages={preparing:'正在准备本次输入，尚未发送。',consent:'等待你核对原生发送预览，尚未发送。',sending:'已确认，正在请求并等待结果；可能已计费。本地记录仍可使用。',ready:'结果已返回，请核对后保存。',cancelled:'本次识别已取消；已发送部分仍可能计费。原草稿保留。',error:'本次识别未完成；本地记录仍可使用。'};$('ai-task-status-text').textContent=message||messages[phase]||messages.error;$('ai-task-cancel').hidden=!busy;$('ai-task-dismiss').hidden=busy;placeBusyAiStatus();}
