window.receiveAiEvent=function(json){if(!window.AiContract)return;let event;try{event=AiContract.validateEvent(json);}catch(_){return;}if(window.Android&&typeof Android.consumeAiEvent==='function'){let claimed=false;try{claimed=!!event.deliveryToken&&Android.consumeAiEvent(event.deliveryToken,event.requestId,event.event)===true;}catch(_){}if(!claimed){if(aiSession&&aiSession.invalidateAttempt(event.clientAttempt)){try{if(typeof Android.cancelAi==='function')Android.cancelAi(event.clientAttempt);}catch(_){}showAiStatus(event.mode,'cancelled','识别会话已失效，旧结果未应用；当前草稿保留。');}return;}}if(event.mode!==mode){invalidateAiMode(event.mode);return;}if(aiSession&&!aiSession.accept(event))return;if(event.event==='started'||event.event==='phase')showAiStatus(event.mode,event.event==='started'?'preparing':event.phase);else if(event.event==='cancelled')showAiStatus(event.mode,'cancelled');else if(event.event==='result'){showAiStatus(event.mode,'ready');offerAiResult(event);}else if(event.event==='error'){showAiStatus(event.mode,'error',event.error+' 本地记录仍可使用。');if(aiLastRequest&&aiLastRequest.clientAttempt===event.clientAttempt){aiFailure={request:aiLastRequest,foodContext:aiLastFoodContext};aiRetry=event.retryable?{request:aiLastRequest,id:event.requestId,foodContext:aiLastFoodContext}:null;$('ai-retry').hidden=!aiRetry;const panel=$('ai-recovery'),host=aiCaptureHost(event.mode);if(host)host.append(panel);$('ai-recovery-message').textContent=aiRetry?'可重新预览同一份内容，每次发送都可能再次收费；也可用原文字手动填写。':'可继续手动填写。原文字仅在本次会话供你核对，不会自动填入或保存。';panel.hidden=false;}}};
